// The language the screens are shown in: the one the person chose, kept
// under languageKey in the browser's local storage across sessions, or the
// specification's language, the first of strings.js.

import { languageKey, languages } from "../strings.js";
import { ref } from "./vue.js";

function stored() {
  try {
    return localStorage.getItem(languageKey);
  } catch {
    return null;
  }
}

/** The language chosen, as a ref the shell draws the screens again from. */
export const language = ref(languages.find((candidate) => candidate === stored()) ?? languages[0]);

/** Chooses a language strings.js holds: it is kept, and the document says it. */
export function choose(chosen) {
  if (!languages.includes(chosen)) {
    return;
  }
  try {
    localStorage.setItem(languageKey, chosen);
  } catch {
    // the choice holds for this page alone when the storage refuses it
  }
  language.value = chosen;
  document.documentElement.lang = chosen;
}

/** A language by its own name, as a speaker of it writes it. */
export function nameOf(code) {
  try {
    return new Intl.DisplayNames([code], { type: "language" }).of(code) ?? code;
  } catch {
    return code;
  }
}
